import{_ as t,o,c as i,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Activities — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Activities — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/activities"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Activities — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/activities"}]]},"headers":[],"relativePath":"user-guide/activities.md","filePath":"user-guide/activities.md","lastUpdated":1787963429000}'),s={name:"user-guide/activities.md"};function r(n,e,c,l,d,m){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="activities-—-user-guide" tabindex="-1">Activities — User Guide <a class="header-anchor" href="#activities-—-user-guide" aria-label="Permalink to &quot;Activities — User Guide&quot;">​</a></h1><h2 id="who-can-use-activities" tabindex="-1">Who can use Activities <a class="header-anchor" href="#who-can-use-activities" aria-label="Permalink to &quot;Who can use Activities&quot;">​</a></h2><p>Your workspace must have the <strong>Activities</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>complete</code> as needed).</p><p>Without <strong>assign</strong>, you only see activities assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Activities</strong> from the sidebar (after Meetings).</p><ul><li>Search by subject or body</li><li>Filter by type, status (open / completed), assignee, or toggle <strong>My Activities</strong></li><li>KPI cards summarize total, my activities, open, completed, and due soon</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted activity from the row menu</li><li><strong>Delete permanently</strong> requires <code>activities.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New activity</strong></li><li>Choose a type (call, email, note, follow-up, other)</li><li>Enter subject (required) and optional body / due date / assignee</li><li>Link at least one <strong>Contact</strong>, <strong>Company</strong>, or <strong>Lead</strong> (pickers appear when those modules are installed)</li><li>Save</li></ol><p>Edit from the row menu or the record page.</p><h2 id="complete" tabindex="-1">Complete <a class="header-anchor" href="#complete" aria-label="Permalink to &quot;Complete&quot;">​</a></h2><p>From the record page (or row menu when available), <strong>Complete</strong> sets the completed timestamp. Open activities have no <code>completed_at</code>.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the engagement</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, complete, and delete/restore events</li></ul><p>When you log or complete an activity linked to a Contact, Company, or Lead, a matching entry appears on that record’s Activity tab.</p>',17)])])}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
